// Gera uma mensagem personalizada para cada cliente com base no perfil e no saldo.

const dados = $input.first().json;

const clientes = dados.body?.clientes ?? [];
const investimentos = dados.investimentos ?? [];

// "R$ 12.500,00" -> 12500
function saldoParaNumero(texto) {
  const limpo = String(texto)
    .replace(/[^\d,]/g, "")   // remove "R$", espaços e pontos de milhar
    .replace(",", ".");       // vírgula decimal -> ponto
  return Number(limpo) || 0;
}

// 12500 -> "R$ 12.500,00"
function formatarMoeda(valor) {
  return valor.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
}

const resultado = clientes.map(cliente => {
  const saldo = saldoParaNumero(cliente.saldo);
  const primeiroNome = cliente.nome.split(" ")[0];

  // Produtos do mesmo perfil que o cliente consegue contratar com o saldo atual
  const opcoes = investimentos.filter(
    inv => inv.perfil === cliente.perfil && Number(inv.minimo) <= saldo
  );

  let mensagem = `Olá, ${primeiroNome}! 👋\n\n`;
  mensagem += `Com base no seu perfil ${cliente.perfil} e no seu saldo de ${formatarMoeda(saldo)}, `;

  if (opcoes.length > 0) {
    mensagem += `separamos estas opções de investimento para você:\n\n`;
    opcoes.forEach(inv => {
      mensagem += `• ${inv.produto} — rentabilidade: ${inv.rentabilidade} (mínimo: ${formatarMoeda(Number(inv.minimo))})\n`;
    });
  } else {
    mensagem += `ainda não encontramos produtos disponíveis para o seu perfil com esse valor. `;
    mensagem += `Que tal conversar com um de nossos especialistas?\n`;
  }

  mensagem += `\nFicamos à disposição para ajudar você a investir melhor. 🚀`;

  return {
    json: {
      nome: cliente.nome,
      email: cliente.email,
      perfil: cliente.perfil,
      saldo,
      assunto: `${primeiroNome}, temos sugestões de investimento para você`,
      mensagem,
    },
  };
});

// Um item por cliente: o próximo nó (Gmail, WhatsApp, Loop etc.) roda uma vez para cada um
return resultado;
